import random
import unittest
from pathlib import Path

from hammodem.ardop import codec


class ArdopCodecTest(unittest.TestCase):
    def test_rs_matches_rockliff_vectors(self):
        # Generated by compiling ardopcf's lib/rockliff/rrs.c (rs_append) on known inputs.
        for line in (Path(__file__).parent / "fixtures" / "ardop_rockliff_rs.txt").read_text().splitlines():
            v = list(map(int, line.split()))
            dl, rl = v[0], v[1]
            data, block = bytes(v[2:2 + dl]), bytes(v[2:2 + dl + rl])
            self.assertEqual(codec.rs_append(data, rl), block)
            self.assertEqual(codec.rs_correct(block, rl), (data, 0))

    def test_rs_corrects(self):
        rng = random.Random(1)
        data = bytes(rng.randrange(256) for _ in range(67))       # count + 64 data + CRC
        block = bytearray(codec.rs_append(data, 32))
        for p in rng.sample(range(len(block)), 16):
            block[p] ^= rng.randrange(1, 256)
        self.assertEqual(codec.rs_correct(bytes(block), 32), (data, 16))

    def test_crc_round_trip_and_frame_type_binding(self):
        blk = codec.append_crc(b"\x10hello ardop", 0x40)
        self.assertTrue(codec.check_crc(blk, 0x40))
        self.assertFalse(codec.check_crc(blk, 0x41))               # the frame type is folded into the CRC

    def test_packed6_and_station_ids(self):
        for s in ("N0CALL", "N0CALL-1", "K7ABC-15", "W1AW-A", "VE3XYZ-9"):
            self.assertEqual(codec.station_from_bytes(codec.station_bytes(s)), s)
        self.assertEqual(codec.unpacked6(codec.packed6("FN31")), "FN31    ")
        with self.assertRaises(ValueError):
            codec.station_bytes("N0CALL-16")

    def test_frame_table(self):
        self.assertEqual(len([f for f in codec.FRAMES.values() if f.mod in ("4PSK", "8PSK", "16QAM")]), 26)   # 13 modes x even/odd
        f = codec.BY_NAME["16QAM.2000.100.O"]
        self.assertEqual((f.code, f.carriers, f.data_len, f.rs_len), (0x75, 8, 128, 64))
        self.assertEqual(codec.mode_codes("4FSK.200.50S"), (0x48, 0x49))

    def test_type_symbols(self):
        syms = codec.type_symbols(0x42, 0xFF)
        self.assertEqual(len(syms), 10)
        self.assertEqual(syms[:4], [1, 0, 0, 2])                    # 0x42 = 01 00 00 10
        self.assertEqual(syms[4], syms[9])                           # both parity symbols from the first byte


if __name__ == "__main__":
    unittest.main()


class ArdopModulateTest(unittest.TestCase):
    """Structure checks; interop is verified against ardopcf --decodewav (lab/ARDOP_*.md)."""

    def test_frame_lengths(self):
        from hammodem.ardop import modulate as m
        e, _ = codec.mode_codes("4FSK.200.50S")
        enc = m.encode_fsk_data(e, b"x" * 10, 0xFF)
        self.assertEqual(len(enc), 2 + 1 + 16 + 2 + 4)            # type x2, count, 16 data, CRC, 4 RS
        x = m.modulate_4fsk(enc, leader_ms=240, trailer_ms=20)
        # leader 12 symbols + 10 type symbols + 23 bytes * 4 symbols, all 240 samples, + trailer (3 x 120 samples for
        # 20 ms) - the 60 samples of filter alignment ardopcf drops
        self.assertEqual(len(x), (12 + 10 + 23 * 4) * 240 + 3 * 120 - 60)
        self.assertEqual(len(m.encode_conreq("N0CALL", "K1ABC", "500M")), 18)

    def test_data_block_crc_and_rs(self):
        from hammodem.ardop import modulate as m
        e, _ = codec.mode_codes("4FSK.500.100S")
        enc = m.encode_fsk_data(e, b"hello", 0x5A)
        self.assertEqual(enc[:2], bytes((e, e ^ 0x5A)))
        block, count = codec.rs_correct(enc[2:], 8)
        self.assertEqual(count, 0)
        self.assertTrue(codec.check_crc(block, e))
        self.assertEqual(block[0], 5)
        self.assertEqual(block[1:6], b"hello")
